def transform(grid):
    h, w = len(grid), len(grid[0])

    # Detect diagonal stripes by their c-r offset. For each offset with
    # a stripe, use its observed color; fill other offsets by repeating the
    # ordered sequence of stripe colors according to the gaps between them.
    known = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                known[c-r] = grid[r][c]

    offsets = sorted(known)
    if not offsets:
        return [row[:] for row in grid]

    # The stripes form a periodic diagonal pattern. Infer the period as the
    # smallest shift that maps every observed stripe to an equal-colored one.
    period = max(offsets) - min(offsets) + 1
    for p in range(1, period + 1):
        if all(known[a] == known[b]
               for a in offsets for b in offsets
               if (a-b) % p == 0):
            period = p
            break

    pattern = {}
    for d, color in known.items():
        pattern[d % period] = color

    # Interpolate unmarked residues in the repeating stripe cycle.
    for k in range(period):
        if k not in pattern:
            before = max((x for x in pattern if x < k), default=None)
            after = min((x for x in pattern if x > k), default=None)
            if before is None:
                before = max(pattern)
            if after is None:
                after = min(pattern)
            pattern[k] = pattern[before] if k-before <= after-k else pattern[after]

    return [[pattern[(c-r) % period] for c in range(w)] for r in range(h)]
